export const DONG_VIEWPORT_ENTRIES: Readonly<
  Record<string, DongViewportEntry>
> = Object.freeze(
  Object.fromEntries(
    DONG_VIEWPORT_DATA.map(
      ([key, codes, west, south, east, north]) => [
        key,
        Object.freeze({
          legalDongCodes: Object.freeze(codes.split('+')),
          west,
          south,
          east,
          north,
        }),
      ],
    ),
  ),
)

export const DONG_VIEWPORTS: Readonly<Record<string, GeographicBounds>> =
  Object.freeze(
    Object.fromEntries(
      Object.entries(DONG_VIEWPORT_ENTRIES).map(([key, entry]) => [
        key,
        Object.freeze({
          west: entry.west,
          south: entry.south,
          east: entry.east,
          north: entry.north,
        }),
      ]),
    ),
  )

export function getDongViewport(
  province: string,
  sigungu: string,
  dong: string,
): GeographicBounds | null {
  return DONG_VIEWPORTS[`${province}|${sigungu}|${dong}`] ?? null
}
